POEMA = "Mañana de invierno\nLa niebla es una manta\nque cubre todo el valle;\nel río se despierta\ny canta por la calle.\nEl sol, como un naranjo,\nse asoma a la ventana;\nlos techos se sonrojan\ny empieza la mañana."
POEMA_L = "«Mañana de invierno». La niebla es una manta / que cubre todo el valle; / el río se despierta / y canta por la calle. // El sol, como un naranjo, / se asoma a la ventana; / los techos se sonrojan / y empieza la mañana. (Una barra / separa los versos y una doble barra // separa las estrofas.)"
L(OA13, 3,
  "Este cuaderno y un lápiz.",
  "Aprenderé a reconocer y usar recursos del poema (verso, estrofa, rima, comparación, metáfora y personificación) para expresar emociones con creatividad.",
  ["Reconozco los géneros que puedo escribir.", "Sé qué es un verso."],
  ["Un poema se escribe en versos, que son las líneas, y se agrupan en estrofas, que son los bloques separados por un espacio. Un poema usa recursos para decir las cosas de manera sugerente. La rima ocurre cuando dos versos terminan con sonidos iguales a partir de la última vocal fuerte, como «valle» y «calle». La comparación une dos cosas con «como» o «parece»: «el sol, como un naranjo».",
   "La metáfora dice que una cosa es otra, sin usar «como»: «la niebla es una manta». La personificación da cualidades humanas a algo que no es humano: «el río se despierta y canta». Con estos recursos transformo lo cotidiano en imágenes, es decir, descripciones que se pueden imaginar con los sentidos.",
   "Para escribir un poema elijo un tema que me despierte una emoción, hago una lluvia de ideas con imágenes (qué veo, oigo, huelo), escojo uno o dos recursos y los pruebo. Puedo escribir con rima o sin ella; lo importante es que cada verso aporte algo. Después leo en voz alta para sentir el ritmo y ajusto las palabras que no suenan bien."],
  [("verso", "cada línea de un poema"), ("estrofa", "grupo de versos separado por un espacio"), ("rima", "sonidos iguales al final de dos versos"), ("comparación", "unión de dos cosas con «como»"), ("personificación", "dar cualidades humanas a algo que no es humano")],
  [("Reconocer recursos", f"Poema: {POEMA_L} ¿Qué recurso aparece en «el río se despierta y canta»?",
    ["Un río no se despierta ni canta como una persona.", "Se le dan cualidades humanas."], "Personificación"),
   ("Contar versos y estrofas", f"Poema: {POEMA_L} ¿Cuántos versos y cuántas estrofas tiene, sin contar el título?",
    ["La doble barra separa dos estrofas.", "Cada estrofa tiene 4 versos, así que en total son 8 versos."], "8 versos y 2 estrofas")],
  [("Confundir comparación con metáfora.", "La comparación usa «como»; la metáfora dice que una cosa es otra.", "Busca la palabra «como» o «parece»."),
   ("Forzar la rima con palabras que no tienen sentido.", "El poema pierde sentido y emoción.", "Prefiere un verso con sentido aunque no rime.")],
  ([E("Un poema se organiza en versos y estrofas. ¿Verdadero o falso?", "Verdadero", "Los versos forman estrofas."),
    E("«El sol, como un naranjo»: ¿es una comparación o una metáfora?", "Una comparación", "Usa la palabra «como»."),
    E("«Valle» y «calle» terminan con sonidos iguales. ¿Qué recurso forman: rima o personificación?", "Rima", "Coinciden los sonidos finales.")],
   [E(f"Poema: {POEMA_L} ¿«La niebla es una manta» es una metáfora o una comparación?", "Una metáfora", "Dice que la niebla es una manta, sin «como»."),
    E("«La luna sonríe desde el cielo». ¿Qué recurso se usa: personificación o rima?", "Personificación", "La luna no sonríe: se le da una cualidad humana."),
    E("«Tus ojos parecen dos lagos». ¿Es una comparación o una metáfora?", "Una comparación", "Usa la palabra «parecen».")],
   [E(f"Poema: {POEMA_L} ¿Qué versos riman con «ventana»: «mañana» o «sonrojan»?", "Mañana", "Ventana y mañana terminan igual."),
    E("¿Qué oración tiene personificación: «El viento silba cansado por las calles» o «El viento sopla fuerte por las calles»?", "El viento silba cansado por las calles", "Se le da cansancio humano al viento."),
    arith("Un poema tiene 3 estrofas de 4 versos cada una. ¿Cuántos versos tiene en total?", "3*4", "Se multiplican las estrofas por los versos de cada una.", " versos")],
   [E("Un estudiante dice: «Mi poema debe rimar todo, aunque quede sin sentido». ¿Es una buena decisión? Responde sí o no.", "No", "El sentido y la emoción importan más que forzar la rima."),
    E("Dos versos: A) «La tarde es un río de oro». B) «La tarde es muy bonita». ¿Cuál usa un recurso poético?", "A", "A es una metáfora que crea una imagen.")],
   [E("Escribe qué recurso usarías para decir que una nube es tan suave como el algodón: comparación o personificación.", "Comparación", "Compara dos cosas con «como»."),
    E("Convierte en metáfora: «Tus manos son como pájaros». ¿Cómo queda: «Tus manos son pájaros» o «Tus manos vuelan sin sentido»?", "Tus manos son pájaros", "Se elimina «como» y se dice que una cosa es otra.")]),
  [E("Para el Día del Libro escribes un poema sobre la lluvia. Quieres dar vida a la lluvia como si fuera una persona. ¿Qué recurso usas: personificación o rima?", "Personificación", "Se le dan acciones humanas a la lluvia.")],
  [E("Nombra un recurso poético.", "Rima, comparación, metáfora o personificación", "Son recursos de la clase."),
   E("¿Qué es una estrofa?", "Un grupo de versos", "Se separa por un espacio."),
   E("¿Para qué leo mi poema en voz alta?", "Para sentir el ritmo y mejorar", "Ayuda a ajustar las palabras.")],
  ("Escribe un poema de dos estrofas de dos o tres versos cada una sobre uno de estos temas: la lluvia, un cerro, una mochila. Incluye al menos una comparación y una personificación. Al final subraya esos recursos y explica en una línea qué emoción quieres transmitir.",
   "La lluvia, como un tambor, / golpea suave el techo. / Las nubes lloran despacio / y el patio se hace espejo. Emoción: tranquilidad.",
   ["dos estrofas", "una comparación", "una personificación", "emoción explicada"], ["el poema y sus recursos subrayados"],
   ["confundir comparación y metáfora", "no explicar la emoción"], "Lee tu poema en voz alta a alguien y pregúntale qué imagen vio."),
  "Describe un objeto de tu casa con una comparación.",
  "Escribe un verso con personificación sobre el viento.")

